  rows.sort((a, b) => {
    if (b.quantitySold !== a.quantitySold) {
      return b.quantitySold - a.quantitySold;
    }
    if (a.productId < b.productId) {
      return -1;
    }
    if (a.productId > b.productId) {
      return 1;
    }
    return 0;
  });
  return rows;
}

