  let total = 0;
  for (let i = 0; i < movements.length; i = i + 1) {
    const movement = movements[i];
    if (movement.reason !== 'Spoiled') {
      continue;
    }
    const t = cbParseTime(movement.timestamp);
    if (Number.isNaN(t)) {
      continue;
